interfaces.contract:
三层管道主入口。

输入 PermissionCheckInput: { toolName: string; command?: string; path?: string; toolInput?: unknown; cwd: string; agentName?: string }
输入 PermissionContext: { mode: PermissionMode; rules: Rule[]; classifier?: ClassifierConfig; signal?: AbortSignal }

返回 PermissionDecision: { action: 'allow'|'deny'|'ask'; reason: string; source: 'ast'|'rule'|'ai'|'mode'; riskLevel?: 'low'|'medium'|'high'; matchedRule?: Rule }

契约：
- mode='yolo' → 直接返回 {action:'allow', source:'mode'}
- mode='strict' → 直接返回 {action:'ask', source:'mode'}（全部人工审批）
- mode='auto'/'approve' → 走三层管道
- 永不 throw，所有异常 fallback 到 {action:'ask', source:'mode', reason:'check failed: ...'}
- 阻塞调用（AI 层可能耗时 1-90s），调用方需考虑超时

层3 AI Classifier。

输入 ToolInvocationContext: { toolName: string; command?: string; path?: string; cwd: string; agentName?: string }
输入 ClassifierConfig: { model: string; timeout: number; autoApproveLowRisk: boolean; autoDenyHighRisk: boolean }
返回 ClassifierResult: { risk_level: 'low'|'medium'|'high'; outcome: 'allow'|'ask'|'deny'; reasoning: string; confidence: number }

契约：
- 用 getApiProvider(model.api).streamSimple() 同进程调用
- system prompt ~150 token，user prompt 含 toolName/command/path/cwd/agentName
- temperature=0, maxTokens=256, 不传 tools
- JSON 输出 + parseClassifierResponse 容错
- 失败/超时/解析失败 → fallback {risk_level:'medium', outcome:'ask'}
- autoApproveLowRisk=false 时 low → ask；autoDenyHighRisk=false 时 high → ask
- 永不 throw（所有异常 catch 后返回 fallback）

dataModels.definition:
/** 四档权限模式，按严格等级排序 */
export type PermissionMode = 'yolo' | 'auto' | 'approve' | 'strict';

export const PERMISSION_MODES: PermissionMode[] = ['yolo', 'auto', 'approve', 'strict'];

export const MODE_DESCRIPTIONS: Record<PermissionMode, string> = {
  yolo: '完全无防护，所有工具调用放行',
  auto: '安全命令规则直接放行 + 非安全命令过 AI 审查 + AI 认为安全放行/AI 认为非安全人工审批',
  approve: '自动模式去除 AI，规则匹配后安全放行、非安全直接人工审批',
  strict: '全部审批',
};

/** 权限规则（层2 用） */
export interface Rule {
  /** 唯一 id（用户规则用 'user-<n>'，内置用 'builtin-safe-<n>'/'builtin-danger-<n>'） */
  id: string;
  /** 工具名匹配模式，wildcard（'*' 匹配全部，'bash' 精确匹配） */
  tool: string;
  /** 命令匹配模式，wildcard（仅 bash 工具用，其他工具 undefined） */
  pattern: string;
  /** 决策动作 */
  action: 'allow' | 'deny' | 'ask';
  /** 规则来源 */
  source: 'builtin-safe' | 'builtin-danger' | 'user';
  /** 可选描述（UI 展示用） */
  description?: string;
}

/** 权限决策结果 */
export interface PermissionDecision {
  /** 最终动作 */
  action: 'allow' | 'deny' | 'ask';
  /** 人类可读的原因（UI 展示 + 拒绝理由回传给 agent） */
  reason: string;
  /** 决策来源（用于审计/调试） */
  source: 'mode' | 'ast' | 'rule' | 'ai' | 'user';
  /** AI 风险等级（仅 source='ai' 时） */
  riskLevel?: 'low' | 'medium' | 'high';
  /** 匹配的规则（仅 source='rule' 时） */
  matchedRule?: Rule;
  /** AI 置信度（仅 source='ai' 时） */
  confidence?: number;
}

/** AI Classifier 配置 */
export interface ClassifierConfig {
  /** 是否启用 AI 层（auto 模式自动 true，其他模式忽略） */
  enabled: boolean;
  /** 模型：'auto'（选最便宜）或 'provider/model-id'（如 'zhipu/glm-4-flash'） */
  model: string;
  /** 超时秒数，默认 90 */
  timeout: number;
  /** 低风险是否自动放行，默认 true */
  autoApproveLowRisk: boolean;
  /** 高风险是否自动拦截（转人工审批），默认 true */
  autoDenyHighRisk: boolean;
}
